CREATE TABLE `attendance_recaps` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `tahun` smallint unsigned NOT NULL,
  `bulan` tinyint unsigned NOT NULL,
  `hari_kerja` tinyint unsigned NOT NULL,
  `hadir` tinyint unsigned NOT NULL DEFAULT '0',
  `perdin` tinyint unsigned NOT NULL DEFAULT '0',
  `cuti` tinyint unsigned NOT NULL DEFAULT '0',
  `sakit` tinyint unsigned NOT NULL DEFAULT '0',
  `ijin` tinyint unsigned NOT NULL DEFAULT '0',
  `alpha` tinyint unsigned NOT NULL DEFAULT '0',
  `telat_hari` tinyint unsigned NOT NULL DEFAULT '0',
  `menit_telat` int unsigned NOT NULL DEFAULT '0',
  `persen_kehadiran` decimal(5,1) NOT NULL DEFAULT '0.0',
  `lokasi_bandung` tinyint unsigned NOT NULL DEFAULT '0',
  `lokasi_jakarta` tinyint unsigned NOT NULL DEFAULT '0',
  `koreksi_by_admin` tinyint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_recaps_employee_id_tahun_bulan_unique` (`employee_id`,`tahun`,`bulan`),
  CONSTRAINT `attendance_recaps_employee_id_foreign` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
